"""Which part of L_{>=1}(sle(n)) is generated by L_1?  G_1 = L_1, G_{j+1} = [L_1, G_j].
The spanning set is reduced to a basis at every step (otherwise it blows up)."""
import sys
from le import abr, rref, padd
from sle import kerdelta, monos, lap


def rowize(ps, cols):
    idx = {c: i for i, c in enumerate(cols)}
    return [{idx[m]: c for m, c in p.items()} for p in ps if p]


def basis_of(ps, cols):
    """row-reduce; return (pivots, reduced rows) and the polynomials of a basis"""
    piv, red = rref(rowize(ps, cols), len(cols))
    out = []
    for r in red:
        out.append({cols[k]: v for k, v in r.items()})
    return piv, red, out


def inspan(p, cols, piv, red):
    idx = {c: i for i, c in enumerate(cols)}
    v = {idx[m]: c for m, c in p.items()}
    for q, r in zip(piv, red):
        if q in v:
            c = v[q]
            for k, val in r.items():
                v[k] = v.get(k, 0) - c * val
                if v[k] == 0:
                    del v[k]
    return not v


for n in range(2, int(sys.argv[1]) + 1):
    L1 = kerdelta(n, 3)
    G = L1
    for j in range(1, int(sys.argv[2]) + 1):
        d = j + 2
        cols = [m for f in monos(n, d) for m in f]
        Lj = kerdelta(n, d)
        piv, red, Gb = basis_of(G, cols)
        miss = [f for f in Lj if not inspan(f, cols, piv, red)]
        print('n=%d  L_%d (deg %d): dim %3d, spanned by iterated [L_1,...]: %3d, missing %d'
              % (n, j, d, len(Lj), len(piv), len(miss)), end='')
        if miss:
            print('   e.g. %s' % ([sorted(f) for f in miss[:2]],))
        else:
            print()
        sys.stdout.flush()
        G = [p for f in L1 for p in [abr(f, g, n)] if p for g in [0]] if False else \
            [p for f in L1 for g in Gb for p in [abr(f, g, n)] if p]
